mapper.insert:
INSERT INTO guitar_oss_cleanup_task (
    object_key, business_type, status, retry_count, next_retry_at, last_error
) VALUES (
    #{objectKey}, #{businessType}, #{status}, #{retryCount}, #{nextRetryAt}, #{lastError}
)

mapper.select:
SELECT id, object_key, business_type, status, retry_count, next_retry_at, last_error, create_time, update_time
FROM guitar_oss_cleanup_task WHERE status='PENDING' AND next_retry_at <= #{now}
ORDER BY next_retry_at ASC, id ASC LIMIT #{limit}

mapper.update:
UPDATE guitar_oss_cleanup_task SET status='PENDING', next_retry_at=#{now},
last_error='OSS cleanup retry recovered stale task', update_time=#{now}
WHERE status='PROCESSING' AND update_time < #{cutoff}
